from scapy.all import *
import matplotlib.pyplot as plt
import numpy as np

# Read the pcap file
packets = rdpcap('ctf_files/constela.pcapng')
sizes = [len(p) for p in packets]

def create_starmap(width=142):
    height = len(sizes) // width
    matrix = np.zeros((height, width))

    # Create 'stars' based on packet sizes
    for i in range(height):
        for j in range(width):
            idx = i * width + j
            if idx < len(sizes):
                # Map large packet sizes (>400) to bright stars
                if sizes[idx] > 500:
                    matrix[i,j] = 2  # Brightest
                elif sizes[idx] > 400:
                    matrix[i,j] = 1  # Medium bright
                elif sizes[idx] > 300:
                    matrix[i,j] = 0.5  # Dim

    return matrix

# Create constellation map
matrix = create_starmap()

# Plot with astronomical theme
plt.figure(figsize=(20, 10))
plt.style.use('dark_background')
plt.imshow(matrix, cmap='hot')
plt.axis('off')
plt.savefig('starmap.png', dpi=300, bbox_inches='tight', pad_inches=0)
plt.close()

# Create text representation
text_map = []
for row in matrix:
    text_row = []
    for val in row:
        if val > 1.5:
            text_row.append('#')  # Brightest stars
        elif val > 0.75:
            text_row.append('*')  # Medium stars
        elif val > 0.25:
            text_row.append('.')  # Dim stars
        else:
            text_row.append(' ')  # Space
    text_map.append(''.join(text_row))

print("Constellation pattern:")
for row in text_map:
    print(row)

# Try to identify any text or patterns
def detect_letter_patterns(matrix, width=142):
    # Look for common character widths and spacing
    rows, cols = matrix.shape
    pattern_points = []

    for i in range(rows):
        row_points = []
        for j in range(cols):
            if matrix[i,j] > 0.75:  # Bright points
                row_points.append(j)
        if row_points:
            pattern_points.append((i, row_points))

    # Look for regular spacing that might indicate text
    spacings = []
    for _, points in pattern_points:
        if len(points) > 1:
            for i in range(len(points)-1):
                spacings.append(points[i+1] - points[i])

    if spacings:
        common_spacings = sorted(set(spacings))
        print("\nCommon spacings between bright points:")
        for spacing in common_spacings[:10]:
            print(f"Spacing of {spacing} pixels occurs {spacings.count(spacing)} times")

detect_letter_patterns(matrix)

