from scapy.all import *
import numpy as np

# Read packets
packets = rdpcap('ctf_files/constela.pcapng')
sizes = [len(p) for p in packets]

# Convert to matrix with width 142
width = 142
height = len(sizes) // width
matrix = np.zeros((height, width))

# Fill matrix with normalized values
for i in range(height):
    for j in range(width):
        idx = i * width + j
        if idx < len(sizes):
            size = sizes[idx]
            # Normalize based on key packet sizes
            if size > 500:
                matrix[i,j] = 2
            elif size > 400:
                matrix[i,j] = 1
            elif size > 300:
                matrix[i,j] = 0.5

# Convert matrix to string representation focusing on potential flag patterns
print("Looking for flag pattern in first few rows:")
for i in range(min(20, height)):
    line = ''
    for j in range(width):
        if matrix[i,j] > 1.5:
            line += '#'
        elif matrix[i,j] > 0.75:
            line += '*'
        elif matrix[i,j] > 0.25:
            line += '.'
        else:
            line += ' '
    print(f"Row {i+1:2d}: {line}")

# Look for 'flag{' pattern
def find_flag_sequence(sizes):
    # Common sequences near flag pattern
    target_sequences = [
        [420, 426, 68],  # Common sequence
        [552, 420, 426], # Another common sequence
    ]

    print("\nLooking for potential flag sequences:")
    for i in range(len(sizes)-5):
        seq = sizes[i:i+3]
        # Check if this is one of our target sequences
        for target in target_sequences:
            if all(abs(a-b) < 10 for a,b in zip(seq, target)):
                print(f"Found sequence at position {i}: {seq}")
                # Print surrounding packet sizes
                print(f"Context: {sizes[max(0,i-5):i+8]}")

find_flag_sequence(sizes)

